"use client";

import { useState, useEffect } from "react";
import { 
  Search, 
  RotateCcw, 
  FileText, 
  Download,
  Filter,
  Calendar
} from "lucide-react";
import { getDaftarRuangan, getRekapUnitByMonth } from "@/services/ppi";

export default function RekapUnitPage() {
  const [loading, setLoading] = useState(false);
  const [rooms, setRooms] = useState<any[]>([]);
  const [dataRekap, setDataRekap] = useState<any[]>([]);
  
  // State Filter (Sesuai Design image_9e3f95)
  const [selectedUnit, setSelectedUnit] = useState("");
  const [selectedMonth, setSelectedMonth] = useState("");

  // Ambil daftar ruangan saat pertama kali load (image_9e4f33)
  useEffect(() => {
    async function fetchRooms() {
      const data = await getDaftarRuangan();
      setRooms(data);
    }
    fetchRooms();
  }, []);

  const handleSearch = async () => {
    if (!selectedUnit || !selectedMonth) {
      return alert("Silakan pilih Ruangan dan Bulan terlebih dahulu.");
    }
    
    setLoading(true);
    try {
      const result = await getRekapUnitByMonth(selectedUnit, selectedMonth);
      setDataRekap(result);
    } catch (error) {
      alert("Gagal mengambil data rekap.");
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setSelectedUnit("");
    setSelectedMonth("");
    setDataRekap([]);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 text-slate-700">
      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800 tracking-tight">Rekap Laporan Unit</h1>
          <p className="text-sm text-slate-500 font-medium font-sans">Pemantauan akumulasi harian per unit kerja RS Arun</p>
        </div>
        <button className="flex items-center gap-2 bg-emerald-50 text-emerald-600 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-emerald-100 hover:bg-emerald-100 transition-all shadow-sm">
          <Download size={16} /> EXCEL REPORT
        </button>
      </div>

      {/* FORM PENCARIAN (Design Identik image_9e3f95) */}
      <div className="bg-white p-2.5 rounded-[2rem] border border-slate-100 shadow-[0_8px_30px_rgb(0,0,0,0.02)] flex flex-col md:flex-row items-center gap-2">
        {/* Dropdown Ruangan (image_9e4f33) */}
        <div className="flex-1 w-full md:w-auto relative group">
          <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Filter size={18} />
          </div>
          <select 
            value={selectedUnit}
            onChange={(e) => setSelectedUnit(e.target.value)}
            className="w-full bg-slate-50/50 border-none pl-12 pr-4 py-3.5 rounded-2xl text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500/10 appearance-none cursor-pointer transition-all"
          >
            <option value="">Semua Ruangan</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>{room.nama_ruangan}</option>
            ))}
          </select>
        </div>

        {/* Input Bulan (Mirip input tanggal image_9e3f95) */}
        <div className="w-full md:w-64 relative group">
          <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Calendar size={18} />
          </div>
          <input 
            type="month" 
            value={selectedMonth}
            onChange={(e) => setSelectedMonth(e.target.value)}
            className="w-full bg-slate-50/50 border-none pl-12 pr-4 py-3.5 rounded-2xl text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500/10 cursor-pointer transition-all"
          />
        </div>

        {/* Action Buttons (image_9e3f95) */}
        <div className="flex items-center gap-2 w-full md:w-auto">
          <button 
            onClick={handleSearch}
            disabled={loading}
            className="flex-1 md:flex-none bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[11px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-slate-800 transition-all active:scale-95 shadow-lg shadow-slate-200 disabled:opacity-50"
          >
            <Search size={18} /> {loading ? "PROSES..." : "CARI DATA"}
          </button>
          
          <button 
            onClick={handleReset}
            className="p-3.5 rounded-2xl border border-slate-100 text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all active:rotate-180 duration-500"
            title="Reset Filter"
          >
            <RotateCcw size={18} />
          </button>
        </div>
      </div>

      {/* TABLE SECTION (Tetap menggunakan design clean yang sebelumnya) */}
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-[0_20px_50px_rgba(0,0,0,0.04)] overflow-hidden">
        {/* Header Tabel... (lanjutkan seperti kode sebelumnya) */}
        <div className="overflow-x-auto">
          <table className="min-w-full border-separate border-spacing-0 font-sans">
             {/* Render data dari state dataRekap di sini */}
          </table>
        </div>
      </div>
    </div>
  );
}